import React, { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowDown, ArrowRight, ArrowUpRight, Bell, CalendarDays, CarFront, Check, ChevronDown, CircleHelp, ClipboardList, Clock3, Compass, DollarSign, Download, ExternalLink, Eye, FileText, LayoutDashboard, LifeBuoy, LogOut, Mail, MapPin, Menu, MessageCircle, Pencil, Plane, Plus, Printer, Search, Settings, ShieldCheck, Sparkles, Trash2, Truck, Upload, UserCheck, UserRound, UserX, Users, Wallet, X } from 'lucide-react';

const fmt=(n)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',maximumFractionDigits:0}).format(n||0);
async function apiRequest(path,options={},token='',base=import.meta.env.VITE_API_URL||''){if(!base)throw new Error('El servidor de acceso aún no está configurado.');const send=async(access)=>fetch(`${base}${path}`,{...options,headers:{'Content-Type':'application/json',...(access?{Authorization:`Bearer ${access}`} :{}),...(options.headers||{})}});let response=await send(token);if(response.status===401&&localStorage.getItem('yuyari_refresh')&&!path.includes('/auth/token')){const refreshed=await fetch(`${base}/api/auth/token/refresh/`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh:localStorage.getItem('yuyari_refresh')})});if(refreshed.ok){const tokens=await refreshed.json();localStorage.setItem('yuyari_access',tokens.access);response=await send(tokens.access)}}const body=await response.json().catch(()=>({}));if(!response.ok){const detail=body.detail||body.non_field_errors?.[0]||Object.values(body).flat().join(' ');throw new Error(detail||'El servidor rechazó la solicitud.')}return body}
const mapService=s=>({...s,client:s.client_display||s.client_name||'',vehicle:s.vehicle_display||s.vehicle_name||'',stops:(s.stops||[]).map(p=>({name:p.name,time:p.arrival_time||'',duration:p.duration_minutes||'',latitude:p.latitude??'',longitude:p.longitude??'',notes:p.notes||''}))});
