const emptyData=()=>Object.fromEntries(['services','clients','contacts','vehicles','transfers','expenses','users'].map(key=>[key,[]]));
async function loadWorkspace(access,user){const role=user.role,sections={services:'services',clients:'clients',contacts:'contacts',vehicles:'vehicles',transfers:'transfers',expenses:'expenses'},endpoints=Object.entries(sections).filter(([key,section])=>user.is_primary_admin||(user.permissions?user.permissions[section]?.view:roleSections[role]?.includes(({services:'Servicios y reservas',clients:'Clientes',contacts:'Contactos',vehicles:'Unidades',transfers:'Trasbordos',expenses:'Gastos'})[key]))).map(([key])=>key);if(user.is_primary_admin)endpoints.push('users');const values=await Promise.all(endpoints.map(key=>apiRequest(`/api/${key}/`,{},access)));const next=emptyData();endpoints.forEach((key,index)=>{const rows=values[index];next[key]=key==='services'?rows.map(mapService):key==='transfers'?rows.map(t=>({...t,reminders:(t.reminders||[]).join(' · ')})):key==='expenses'?rows.map(e=>({...e,service_id:e.service,service:e.service_name})):key==='users'?rows.map(mapUser):rows});return next}
const permissionModules=[['services','Servicios y reservas'],['clients','Clientes'],['contacts','Contactos'],['vehicles','Unidades'],['transfers','Trasbordos'],['expenses','Gastos'],['settings','Configuración']];
