let leafletPromise;
function loadLeaflet(){
 if(window.L)return Promise.resolve(window.L);
 if(leafletPromise)return leafletPromise;
 leafletPromise=new Promise((resolve,reject)=>{
  if(!document.getElementById('leaflet-css')){const link=document.createElement('link');link.id='leaflet-css';link.rel='stylesheet';link.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(link)}
  const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.async=true;script.onload=()=>window.L?resolve(window.L):reject(new Error('No se pudo iniciar el mapa'));script.onerror=()=>reject(new Error('No se pudo cargar el mapa'));document.head.appendChild(script);
 }).catch(error=>{leafletPromise=null;throw error});
 return leafletPromise;
}
function routePoints(route={}){
 const points=[{key:'origin',label:'Origen',latitude:route.origin_latitude,longitude:route.origin_longitude}];
 (route.stops||[]).forEach((stop,index)=>points.push({key:`stop-${index}`,label:`Parada ${index+1}: ${stop.name||'Sin nombre'}`,latitude:stop.latitude,longitude:stop.longitude}));
 points.push({key:'destination',label:'Destino',latitude:route.destination_latitude,longitude:route.destination_longitude});
 return points.filter(point=>point.latitude!==''&&point.longitude!==''&&point.latitude!=null&&point.longitude!=null&&Number.isFinite(Number(point.latitude))&&Number.isFinite(Number(point.longitude))&&Math.abs(Number(point.latitude))<=90&&Math.abs(Number(point.longitude))<=180);
}
function RouteMap({route,editable=false,activePoint='origin',onPick}){
 const host=useRef(null),map=useRef(null),layer=useRef(null),picker=useRef(onPick),active=useRef(activePoint),[state,setState]=useState('loading'),[tilesFailed,setTilesFailed]=useState(false);
 picker.current=onPick;active.current=activePoint;
 const fingerprint=JSON.stringify({origin_latitude:route.origin_latitude,origin_longitude:route.origin_longitude,destination_latitude:route.destination_latitude,destination_longitude:route.destination_longitude,stops:route.stops||[]});
 useEffect(()=>{let alive=true;let instance;loadLeaflet().then(L=>{if(!alive||!host.current)return;instance=L.map(host.current,{scrollWheelZoom:false}).setView([-15.64,-71.60],10);map.current=instance;layer.current=L.layerGroup().addTo(instance);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).on('tileerror',()=>alive&&setTilesFailed(true)).addTo(instance);instance.on('click',event=>{if(picker.current)picker.current(active.current,event.latlng.lat,event.latlng.lng)});setState('ready');setTimeout(()=>instance.invalidateSize(),80)}).catch(()=>alive&&setState('error'));return()=>{alive=false;if(instance){instance.off();instance.remove()}map.current=null;layer.current=null}},[]);
 useEffect(()=>{if(state!=='ready'||!map.current||!layer.current)return;const L=window.L,points=routePoints(route);layer.current.clearLayers();const latlngs=[];points.forEach((point,index)=>{const latlng=[Number(point.latitude),Number(point.longitude)];latlngs.push(latlng);L.circleMarker(latlng,{radius:8,color:'#fff',weight:2,fillColor:point.key===activePoint?'#c4f74b':index===0?'#1d684f':'#ca7544',fillOpacity:1}).addTo(layer.current).bindTooltip(`${index+1}. ${point.label}`)});if(latlngs.length>1)L.polyline(latlngs,{color:'#1d684f',weight:4,opacity:.82,dashArray:'7 8'}).addTo(layer.current);if(latlngs.length>1)map.current.fitBounds(L.latLngBounds(latlngs),{padding:[30,30],maxZoom:13});else if(latlngs.length===1)map.current.setView(latlngs[0],13);else map.current.setView([-15.64,-71.60],10);setTimeout(()=>map.current?.invalidateSize(),80)},[state,fingerprint,activePoint]);
 return <div className={`route-map ${editable?'route-map-editable':''}`}><div className="route-map-host" ref={host} aria-label="Mapa de ruta y paradas"/>{state==='loading'&&<div className="route-map-message">Cargando mapa…</div>}{state==='error'&&<div className="route-map-message">No se pudo cargar el mapa; puedes continuar con la ruta escrita.</div>}{tilesFailed&&state==='ready'&&<div className="route-map-warning">El mapa base no responde. Puedes seguir consultando la ruta escrita.</div>}<p>{editable?'Haz clic en el mapa para ubicar el punto seleccionado.':'Vista referencial del itinerario.'} Los puntos y la ruta permanecen visibles en texto si falla el mapa. © OpenStreetMap contributors.</p></div>
}

function csvCell(value){let text=String(value??'').replace(/\r\n|\r|\n/g,' · ');if(/^[\s]*[=+@]/.test(text)||/^[\s]*-[A-Za-z]/.test(text))text=`'${text}`;return `"${text.replaceAll('"','""')}"`}
function whatsappHref(phone,message=''){const digits=String(phone||'').replace(/\D/g,'');const number=digits.length===9?`51${digits}`:digits;return `https://wa.me/${number}?text=${encodeURIComponent(message)}`}
function downloadCsv(headers,rows,filename){const csv='\uFEFFsep=;\r\n'+[headers,...rows].map(row=>row.map(csvCell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadExcel(headers,rows,filename,title='Reporte de operaciones') { const esc=value=>String(value??'—').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').split(String.fromCharCode(13)).join('&#10;').split(String.fromCharCode(10)).join('&#10;'); const cell=(value,style='Cell')=>`<Cell ss:StyleID="${style}"><Data ss:Type="String">${esc(value)}</Data></Cell>`; const rowsXml=[`<Row>${cell(title,'Title')}</Row>`,`<Row>${cell(`AEO Yuyari · Generado ${new Date().toLocaleString('es-PE')}`,'Subtitle')}</Row>`,`<Row>${headers.map(header=>cell(header,'Header')).join('')}</Row>`,...(rows.length?rows.map((row,index)=>`<Row>${row.map(value=>cell(value,index%2?'Alt':'Cell')).join('')}</Row>`):[`<Row>${cell('No hay registros para mostrar','Cell')}</Row>`])].join('');const xml=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Default" ss:Name="Normal"><Alignment ss:Vertical="Top" ss:WrapText="1"/><Font ss:FontName="Arial" ss:Size="10" ss:Color="#24382E"/></Style><Style ss:ID="Title"><Alignment ss:Vertical="Center"/><Font ss:FontName="Arial" ss:Size="16" ss:Bold="1" ss:Color="#FFFFFF"/><Interior ss:Color="#174F3C" ss:Pattern="Solid"/></Style><Style ss:ID="Subtitle"><Font ss:FontName="Arial" ss:Size="10" ss:Color="#54705C"/><Interior ss:Color="#EDF4EE" ss:Pattern="Solid"/></Style><Style ss:ID="Header"><Font ss:FontName="Arial" ss:Size="10" ss:Bold="1" ss:Color="#234532"/><Interior ss:Color="#DCEADE" ss:Pattern="Solid"/><Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#B7CABB"/></Borders></Style><Style ss:ID="Cell"><Alignment ss:Vertical="Top" ss:WrapText="1"/><Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#E2E9E2"/></Borders></Style><Style ss:ID="Alt"><Alignment ss:Vertical="Top" ss:WrapText="1"/><Interior ss:Color="#F3F7F3" ss:Pattern="Solid"/><Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#E2E9E2"/></Borders></Style></Styles><Worksheet ss:Name="${esc(title.slice(0,31))}"><Table ss:ExpandedColumnCount="${headers.length}" ss:ExpandedRowCount="${rows.length+3}">${rowsXml}</Table><WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel"><FreezePanes/><FrozenRows>3</FrozenRows><SplitHorizontal>3</SplitHorizontal><TopRowBottomPane>3</TopRowBottomPane></WorksheetOptions></Worksheet></Workbook>`;const url=URL.createObjectURL(new Blob([xml],{type:'application/vnd.ms-excel;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000) }
